import { line } from 'axylo';

// A plain decimal string, as Axylo defines it for `parse: 'number'`: '40', '-1.5', '1e3'.
const PLAIN_DECIMAL = /^-?(?:\d+\.?\d*|\.\d+)(?:[eE][-+]?\d+)?$/;

/**
 * The revenue field arrives as a mix of numbers and decimal strings ("1438.75" beside 1705.25).
 * Axylo rejects every string in a field that also holds a number (AX106), `parse: 'number'` included,
 * so the plain decimal strings are converted here. Rows whose revenue is already a number (or null)
 * are passed through as the caller's own objects. Any other value is left as it is, so that Axylo
 * still reports it and tells the reader rather than this code guessing at it.
 * Row order and count are kept, so row numbers in diagnostics refer to the caller's data.
 */
function normalizeRows(rows) {
  return rows.map((row) => {
    const value = row?.revenue;
    if (typeof value === 'string' && PLAIN_DECIMAL.test(value)) {
      return { ...row, revenue: Number(value) };
    }
    return row;
  });
}

/** The options `render` passes to Axylo; exported so they can be checked with `validate()` in Node. */
export function chartOptions(data) {
  return {
    title: 'Daily store revenue',
    data: normalizeRows(data),
    // Each day is sent as a UTC midnight. `type: 'date'` reads it as that calendar day in every time
    // zone; without it the values are instants and west of UTC each lands on the day before (AX111).
    x: { field: 'day', type: 'date' },
    y: {
      field: 'revenue',
      label: 'Revenue',
      format: { minimumFractionDigits: 2, maximumFractionDigits: 2 },
    },
  };
}

/**
 * Draws the daily revenue line chart into `element` and returns the Axylo chart handle.
 * Rows may come in any order: Axylo draws a line in x order.
 */
export default function render(element, data) {
  return line(element, chartOptions(data));
}

