input.command:
TZ=America/New_York node --input-type=module -e "
import render, { chartOptions } from './chart.js';
import { validate } from 'axylo';
import { readFileSync } from 'node:fs';
const rows = JSON.parse(readFileSync('data.json', 'utf8'));
const opts = chartOptions(rows);
console.log('default export is function:', typeof render === 'function', 'arity', render.length);
console.log('rows in/out:', rows.length, opts.data.length);
console.log('revenue types:', opts.data.map(r => typeof r.revenue).join(','));
console.log('unchanged rows are caller objects:', opts.data.filter((r, i) => r === rows[i]).length);
console.log('input rows not mutated:', JSON.stringify(rows) === readFileSync('data.json','utf8').replace(/\s+/g,'').length ? '' : JSON.stringify(rows.map(r=>typeof r.revenue)));
const problems = validate('line', opts);
for (const d of problems) console.log(d.code, d.level, d.message);
const blocking = problems.filter(d => d.level !== 'hint');
console.log('blocking:', blocking.length);
"

